import os
from typing import Dict, Any, List

from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


def extract_key_value_pairs(file_path: str) -> Dict[str, str]:
    endpoint = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = os.environ["AZURE_FORM_RECOGNIZER_KEY"]

    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            "prebuilt-document",
            document=f,
        )
    result = poller.result()

    extracted: Dict[str, str] = {}

    for kv in result.key_value_pairs or []:
        key = (kv.key.content or "").strip() if kv.key else ""
        value = (kv.value.content or "").strip() if kv.value else ""
        if key:
            extracted[key] = value

    return extracted


def extract_layout(file_path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = os.environ["AZURE_FORM_RECOGNIZER_KEY"]

    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            "prebuilt-layout",
            document=f,
        )
    result = poller.result()

    pages: List[Dict[str, Any]] = []
    for page in result.pages:
        page_data: Dict[str, Any] = {
            "page_number": page.page_number,
            "width": page.width,
            "height": page.height,
            "unit": page.unit,
            "lines": [],
            "words": [],
        }

        for line in page.lines or []:
            page_data["lines"].append(
                {
                    "content": line.content,
                    "polygon": list(line.polygon) if line.polygon else None,
                }
            )

        for word in page.words or []:
            page_data["words"].append(
                {
                    "content": word.content,
                    "confidence": word.confidence,
                    "polygon": list(word.polygon) if word.polygon else None,
                }
            )

        pages.append(page_data)

    tables: List[Dict[str, Any]] = []
    for table in result.tables or []:
        table_data: Dict[str, Any] = {
            "row_count": table.row_count,
            "column_count": table.column_count,
            "cells": [],
        }
        for cell in table.cells or []:
            table_data["cells"].append(
                {
                    "row_index": cell.row_index,
                    "column_index": cell.column_index,
                    "content": cell.content,
                    "bounding_regions": [
                        {
                            "page_number": br.page_number,
                            "polygon": list(br.polygon) if br.polygon else None,
                        }
                        for br in (cell.bounding_regions or [])
                    ],
                }
            )
        tables.append(table_data)

    return {
        "pages": pages,
        "tables": tables,
    }
